/* Scripture Launchpad — Doctrine & Covenants, part 1: sections 1-20 */
window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _dc = SLP.books.find(function(b){ return b.id === "dc"; });
if (!_dc) throw new Error("data/canon.js must load before dc-01-foundations.js");
(_dc.chapters = _dc.chapters || []).push(
  { n:1, summary:"Given as the preface to the book of commandments, this revelation sounded the voice of warning to all people through disciples chosen in the last days. The Lord declared that His voice would reach every ear and heart, that the rebellious would be pierced with sorrow, and that those who would not hear His prophets would be cut off, having strayed from His ordinances and broken His everlasting covenant. Knowing the calamity which should come upon the inhabitants of the earth, the Lord called His servant Joseph Smith and gave commandments, so that the weak things of the world might break down the mighty and strong ones, that faith might increase, and that the fulness of the gospel might be proclaimed by the weak and simple. The commandments came in weakness, after the manner of their language, that the church might be brought out of obscurity, that repentant servants would be forgiven, and that the word of the Lord would not pass away but all be fulfilled.",
    context:"Given through Joseph Smith on November 1, 1831, at Hiram, Ohio, as the Lord's preface to His book of commandments.",
    keyVerses:[
      { ref:"D&C 1:19", text:"The weak things of the world shall come forth and break down the mighty and strong ones, that man should not counsel his fellow man, neither trust in the arm of flesh" },
      { ref:"D&C 1:30", text:"And also those to whom these commandments were given, might have power to lay the foundation of this church, and to bring it forth out of obscurity and out of darkness" },
      { ref:"D&C 1:38", text:"What I the Lord have spoken, I have spoken, and I excuse not myself; and though the heavens and the earth pass away, my word shall not pass away" }
    ],
    takeaway:"The Lord works through weak servants who trust Him, so that faith and His covenant can be established.",
    quiz:[
      { q:"Whom did the Lord say He called upon and spoke to from heaven because of the coming calamity?", choices:["Joseph Smith, Jun.","Martin Harris","Oliver Cowdery","Sidney Rigdon"], a:0, why:"The Lord said that knowing the calamity which should come, He called upon His servant Joseph Smith, Jun., and gave him commandments." },
      { q:"What does the Lord promise to the person who repents and does His commandments?", choices:["He will be spared all trials","He shall be forgiven","He will receive riches and honor","He will never be chastened"], a:1, why:"He who repents and does the commandments shall be forgiven, for the Lord cannot look upon sin with the least degree of allowance." },
      { q:"Why did the Lord choose the weak and simple to proclaim His gospel?", choices:["Because no strong men were available","So the work would move slowly and safely","So man would not trust in the arm of flesh","Because the gospel was meant only for the poor"], a:2, why:"The weak things were sent to break down the mighty and strong ones, so man would not trust in the arm of flesh." }
    ] },
  { n:2, summary:"Moroni delivered the Lord's promise that He would reveal the priesthood by the hand of Elijah the prophet before the coming of the great and dreadful day of the Lord. Elijah would plant in the hearts of the children the promises made to the fathers, and the hearts of the children would turn to their fathers. The revelation explained that if this turning did not happen, the whole earth would be utterly wasted at the Lord's coming. Though only three verses long, the promise pointed to the restoration of priesthood authority and to work that would bind generations of families together in preparation for the day of the Lord. It stands among the first revelations recorded in this dispensation and introduced a theme that shaped the latter-day temple movement.",
    context:"Words of Moroni to Joseph Smith in September 1823, quoting the Lord's promise about Elijah's coming ministry.",
    keyVerses:[
      { ref:"D&C 2:1", text:"Behold, I will reveal unto you the Priesthood, by the hand of Elijah the prophet, before the coming of the great and dreadful day of the Lord." },
      { ref:"D&C 2:2", text:"And he shall plant in the hearts of the children the promises made to the fathers, and the hearts of the children shall turn to their fathers." }
    ],
    takeaway:"Turning our hearts to our ancestors prepares the earth for the Lord's coming.",
    quiz:[
      { q:"By whose hand did the Lord promise to reveal the priesthood?", choices:["Moses","Elijah the prophet","John the Baptist","Peter, James, and John"], a:1, why:"The Lord said He would reveal the priesthood by the hand of Elijah the prophet before the great and dreadful day of the Lord." },
      { q:"What did Elijah plant in the hearts of the children?", choices:["The law of sacrifice","The names of all nations","The promises made to the fathers","The record of the Nephites"], a:2, why:"Elijah was to plant in the hearts of the children the promises made to the fathers, turning the hearts of the children to their fathers." },
      { q:"What consequence did the Lord name if the hearts of the children did not turn to their fathers?", choices:["The priesthood would cease to function","The scriptures would be altered","The church would be scattered","The whole earth would be utterly wasted at His coming"], a:3, why:"The revelation states that if it were not so, the whole earth would be utterly wasted at His coming." }
    ] },
  { n:3, summary:"After Martin Harris persuaded Joseph Smith to let him take the translated manuscript and then lost it, the Lord declared that the works and designs and purposes of God cannot be frustrated. God does not walk in crooked paths, and it is not His work but the work of men that fails. The Lord rebuked Joseph for fearing man more than God, for boasting in his own strength, and for setting at naught the counsels of God, and told him he had lost his privileges for a season by delivering the sacred writings to a wicked man. Yet the Lord was merciful: if Joseph repented, he would still be chosen and again called to the work. The Lord affirmed that His work would go forth, that the knowledge of a Savior would come to the Lamanites through the testimony of their fathers, and that the plates were preserved to fulfill the promises made to His people.",
    context:"Given through Joseph Smith in July 1828 at Harmony, Pennsylvania, after Martin Harris lost the translated manuscript pages.",
    keyVerses:[
      { ref:"D&C 3:1", text:"The works, and the designs, and the purposes of God cannot be frustrated, neither can they come to naught." },
      { ref:"D&C 3:4", text:"For although a man may have many revelations, and have power to do many mighty works, yet if he boasts in his own strength, and sets at naught the counsels of God" }
    ],
    takeaway:"God's purposes cannot be frustrated; fear God rather than man and repent quickly when you fall.",
    quiz:[
      { q:"Why did Joseph lose the gift to translate for a season, according to this section?", choices:["He grew too ill to continue","Persecutors seized the plates","He delivered the sacred writings into the hands of a wicked man","The Lord needed him to preach instead"], a:2, why:"Joseph was told that when he delivered up the sacred writings to a wicked man, he lost his privileges for a season." },
      { q:"What does the Lord say about a man who receives revelations but boasts in his own strength?", choices:["He will be given greater revelations","He must fall and incur the vengeance of a just God","He will be translated like Moses","His weakness will be overlooked"], a:3, why:"Boasting in one's own strength and setting at naught God's counsels brings a fall and the vengeance of a just God." },
      { q:"What did the Lord say the preserved plates would help accomplish for the Lamanites?", choices:["That they might come to the knowledge of their fathers and believe the gospel","That they would move east and join the church","That they would be free from all wars","That their language would be preserved unchanged"], a:0, why:"The plates were preserved so the Lamanites might know the promises of the Lord, believe the gospel, and be saved through repentance." }
    ] },
  { n:4, summary:"The Lord announced that a marvelous work was about to come forth among the children of men and told those who embark in His service to serve Him with all their heart, might, mind, and strength so they could stand blameless before God at the last day. Desire to serve God, the revelation taught, is itself a call to the work, and the field is white already to harvest; those who thrust in the sickle with their might lay up salvation for their souls. Faith, hope, charity, and love, with an eye single to the glory of God, qualify a person for the work, along with virtue, knowledge, temperance, patience, brotherly kindness, godliness, humility, and diligence. The section closed with the promise that those who ask receive and those who knock find the door opened.",
    context:"Given through Joseph Smith in February 1829 at Harmony, Pennsylvania, for his father, Joseph Smith Sr.",
    keyVerses:[
      { ref:"D&C 4:2", text:"Therefore, O ye that embark in the service of God, see that ye serve him with all your heart, might, mind and strength, that ye may stand blameless before God at the last day." },
      { ref:"D&C 4:3", text:"Therefore, if ye have desires to serve God ye are called to the work" },
      { ref:"D&C 4:5", text:"And faith, hope, charity and love, with an eye single to the glory of God, qualify him for the work." }
    ],
    takeaway:"Desire plus wholehearted service qualifies you for the Lord's growing harvest.",
    quiz:[
      { q:"What does the Lord say qualifies a person for His work?", choices:["Priesthood office and education","Wealth and influence","Visionary dreams","Faith, hope, charity and love, with an eye single to the glory of God"], a:3, why:"Section 4 teaches that faith, hope, charity and love, with an eye single to the glory of God, qualify him for the work." },
      { q:"How is the field described as the marvelous work comes forth?", choices:["White already to harvest","Overgrown with thorns","Barren and dry","Ready for planting"], a:0, why:"The Lord pictured the field as white already to harvest, urging laborers to thrust in the sickle with their might." },
      { q:"What principle makes desire to serve God meaningful, according to this section?", choices:["Only the ordained may serve","If ye have desires to serve God, ye are called to the work","Service must wait until perfection","Desire matters less than talent"], a:1, why:"The revelation declares that desire itself constitutes a call, so willing hearts may enter the work and bring salvation to their souls." }
    ] },
  { n:5, summary:"When Martin Harris pressed for a witness of the gold plates, the Lord answered that Joseph Smith had covenanted not to show the plates except to those the Lord commanded, and that Joseph's first gift was to translate, which he was to pretend to no other gift until his purpose was fulfilled. The Lord warned this unbelieving and stiffnecked generation that His word would stand, and He promised three additional witnesses whom He would call and ordain, to whom He would show the plates, so that their testimony would go forth with Joseph's words. The Lord instructed Martin to humble himself in mighty prayer and faith; then he could testify that he had seen the things shown to Joseph by the power of God. Joseph was also commanded to repent, yield no more to the persuasions of men, and stop translating for a season until commanded again.",
    context:"Given through Joseph Smith in March 1829 at Harmony, Pennsylvania, when Martin Harris sought a witness of the plates.",
    keyVerses:[
      { ref:"D&C 5:4", text:"And you have a gift to translate the plates; and this is the first gift that I bestowed upon you" },
      { ref:"D&C 5:11", text:"And in addition to your testimony, the testimony of three of my servants, whom I shall call and ordain, unto whom I will show these things" },
      { ref:"D&C 5:34", text:"Yea, for this cause I have said: Stop, and stand still until I command thee, and I will provide means whereby thou mayest accomplish the thing which I have commanded thee." }
    ],
    takeaway:"God confirms His work through multiple witnesses when we approach Him in humility and faith.",
    quiz:[
      { q:"Who desired a witness of the plates, according to the opening of this section?", choices:["Martin Harris","Oliver Cowdery","David Whitmer","Hyrum Smith"], a:0, why:"The revelation opens by noting that the Lord's servant Martin Harris desired a witness that Joseph had the plates." },
      { q:"How many additional witnesses did the Lord promise to call and ordain who would see the plates?", choices:["Two","Four","Three","Eight"], a:2, why:"The Lord promised the testimony of three servants whom He would show the plates, so their testimony would go forth with the words given through Joseph." },
      { q:"What condition did the Lord set before Martin Harris could receive the view he desired?", choices:["Paying Joseph for the manuscript","Gathering signatures from scholars","Waiting for the church to be organized","Humbling himself in mighty prayer and faith"], a:3, why:"The Lord said if Martin bowed down and humbled himself in mighty prayer and faith, He would grant a view of the things he desired to see." }
    ] },
  { n:6, summary:"As Oliver Cowdery served as Joseph Smith's scribe, he asked the Lord and received this answer declaring that a great and marvelous work was about to come forth and that the field was white already to harvest. Oliver was told to keep the commandments, seek to bring forth and establish the cause of Zion, and seek not riches but wisdom, for he that hath eternal life is rich. The Lord affirmed that Oliver had a gift for finding out mysteries and admonished him to stand by Joseph faithfully, to admonish him of his faults and receive admonition in turn. Recalling the peace Oliver had felt the night he cried to know the truth, the Lord asked what greater witness could be given than from God, granted Oliver the gift to translate, and instructed: look unto me in every thought; doubt not, fear not.",
    context:"Given through Joseph Smith in April 1829 at Harmony, Pennsylvania, in answer to scribe Oliver Cowdery's desire for guidance.",
    keyVerses:[
      { ref:"D&C 6:7", text:"Seek not for riches but for wisdom, and behold, the mysteries of God shall be unfolded unto you, and then shall you be made rich." },
      { ref:"D&C 6:23", text:"Did I not speak peace to your mind concerning the matter? What greater witness can you have than from God?" },
      { ref:"D&C 6:36", text:"Look unto me in every thought; doubt not, fear not." }
    ],
    takeaway:"God answers sincere inquiry with peace to the mind; press forward in faith without doubt or fear.",
    quiz:[
      { q:"What did the Lord remind Oliver of when he desired a further witness?", choices:["The night he cried unto the Lord and felt peace in his mind","An angelic visitation in his childhood","A dream about the plates","The words of his grandfather"], a:0, why:"The Lord told Oliver to cast his mind upon the night he cried unto Him, when He spoke peace to his mind concerning the matter." },
      { q:"What did the Lord say Oliver should seek instead of riches?", choices:["Honor among men","Rest and leisure","Land and prosperity","Wisdom"], a:3, why:"Oliver was told to seek not for riches but for wisdom, and the mysteries of God would be unfolded and he would be made rich." },
      { q:"Why did the Lord say rejection by others could still leave Oliver blessed?", choices:["Because rejection shortens trials","Because they could do no more to him than they did to Christ","Because he would be hidden from enemies","Because others would defend him"], a:1, why:"They could do no more unto Oliver than they did unto the Lord, and he would dwell with Him in glory." }
    ] },
  { n:7, summary:"While translating, Joseph Smith and Oliver Cowdery inquired of the Lord concerning the passage in which Peter asked about the beloved disciple John, and this translation of a record written by John himself answered the question. The Lord asked John what he desired, and John requested power over death so he might live and bring souls to the Lord. Because of that desire, John was granted that he should tarry until the Lord came in glory, prophesying before nations, kindreds, tongues, and people. The Lord explained that Peter had desired to speedily come unto Him in His kingdom, a good desire, while John had desired a greater work among men. John was to be made a flaming fire and a ministering angel, serving those who are heirs of salvation, and Peter, James, and John held the keys of this ministry until the Lord comes.",
    context:"Given through Joseph Smith in April 1829 at Harmony, Pennsylvania, as a translation of a parchment written by the Apostle John.",
    keyVerses:[
      { ref:"D&C 7:2", text:"And I said unto him: Lord, give unto me power over death, that I may live and bring souls unto thee." },
      { ref:"D&C 7:3", text:"And the Lord said unto me: Verily, verily, I say unto thee, because thou desirest this thou shalt tarry until I come in my glory, and shalt prophesy before nations, kindreds, tongues and people." }
    ],
    takeaway:"Righteous desires shape our eternal service; wanting to bless others draws power from God.",
    quiz:[
      { q:"What did John ask of the Lord when given the chance to request anything?", choices:["Riches and honor","Power over death, that he might live and bring souls unto the Lord","Forgiveness for his doubts","A vision of the last days"], a:1, why:"John answered the Lord's question by asking for power over death so he could live and bring souls unto Him." },
      { q:"What did the Lord say Peter had desired?", choices:["To speedily come unto the Lord in His kingdom","To write more scripture","To lead the church on earth","To tarry and prophesy"], a:0, why:"The Lord explained that Peter desired to speedily come unto Him in His kingdom, and called this a good desire." },
      { q:"How was John to serve after receiving his desire?", choices:["As a silent hermit","As a traveling merchant","As king in Jerusalem","As a ministering angel for those who are heirs of salvation"], a:3, why:"The Lord said He would make John as flaming fire and a ministering angel to minister for those who shall be heirs of salvation." }
    ] },
  { n:8, summary:"Speaking to Oliver Cowdery, the Lord promised that as surely as he asked in faith with an honest heart, he would receive knowledge concerning the engravings of the ancient records containing parts of scripture. Revelation, the Lord explained, comes by the Holy Ghost, telling a person in the mind and in the heart, the same spirit by which Moses led the children of Israel through the Red Sea on dry ground. This spirit of revelation was identified as Oliver's gift, one that would deliver him out of the hands of his enemies. Oliver also held the gift of Aaron, a power by which marvelous works could be done, and no power could take it from his hands because it was the work of God. The Lord closed with a caution that without faith a person can do nothing, urging Oliver to trifle not with sacred things.",
    context:"Given through Joseph Smith in April 1829 at Harmony, Pennsylvania, to encourage Oliver Cowdery's attempts to translate.",
    keyVerses:[
      { ref:"D&C 8:2", text:"Yea, behold, I will tell you in your mind and in your heart, by the Holy Ghost, which shall come upon you and which shall dwell in your heart." },
      { ref:"D&C 8:3", text:"Now, behold, this is the spirit of revelation; behold, this is the spirit by which Moses brought the children of Israel through the Red Sea on dry ground." },
      { ref:"D&C 8:10", text:"Remember that without faith you can do nothing; therefore ask in faith. Trifle not with these things; do not ask for that which you ought not." }
    ],
    takeaway:"Revelation comes to both mind and heart through the Holy Ghost when we ask in faith.",
    quiz:[
      { q:"Through what means did the Lord say He would tell Oliver things?", choices:["Visits from angels","Dreams at night","In his mind and in his heart by the Holy Ghost","The voice of Moses"], a:2, why:"The Lord promised to tell Oliver in his mind and in his heart by the Holy Ghost, which would dwell in his heart." },
      { q:"What earlier prophet did the Lord cite as an example of the spirit of revelation?", choices:["Abraham","Moses","Elijah","Enoch"], a:1, why:"The Lord said this is the spirit by which Moses brought the children of Israel through the Red Sea on dry ground." },
      { q:"What limitation did the Lord place on Oliver's gifts?", choices:["They worked only at night","They required fasting for seven days","They operated only near the plates","Without faith he could do nothing"], a:3, why:"The Lord reminded Oliver that without faith he can do nothing, so he must ask in faith and not trifle with sacred things." }
    ] },
  { n:9, summary:"When Oliver Cowdery's attempt to translate failed, the Lord gently explained why. Because Oliver did not continue as he commenced and instead of translating took up writing for Joseph Smith, the privilege was taken from him, and other records would later be given him power to assist translating. The Lord revealed the principle Oliver had lacked: he had supposed he needed only to ask, but he must study the matter out in his mind and then ask if it were right. If it was right, his bosom would burn within him and he would feel it was right; if not, he would experience a stupor of thought that would make the wrong thing fade from his mind. Told not to murmur, for the Lord had given Joseph sufficient strength, Oliver was commanded to do what he had been called to do and stand fast.",
    context:"Given through Joseph Smith in April 1829 at Harmony, Pennsylvania, after Oliver Cowdery tried and failed to translate.",
    keyVerses:[
      { ref:"D&C 9:8", text:"But, behold, I say unto you, that you must study it out in your mind; then you must ask me if it be right, and if it is right I will cause that your bosom shall burn within you" },
      { ref:"D&C 9:9", text:"But if it be not right you shall have no such feelings, but you shall have a stupor of thought that shall cause you to forget the thing which is wrong" }
    ],
    takeaway:"Study matters out in your mind, then ask God; He confirms truth to the heart.",
    quiz:[
      { q:"What work did the Lord say Oliver was called to do at that time?", choices:["Preaching to the Lamanites","Translating the plates of Ether","Building up the church in Missouri","Writing for Joseph Smith"], a:3, why:"The Lord told Oliver that the work he was called to do was to write for His servant Joseph." },
      { q:"What did Oliver misunderstand about receiving the gift to translate?", choices:["That it required ordination first","That it came only through fasting","That he needed only to ask without taking thought","That Joseph must give it to him"], a:2, why:"Oliver supposed the Lord would simply give it to him when he took no thought save it was to ask." },
      { q:"What does the Lord cause a person to feel when a choice is right?", choices:["A burning in the bosom","A stunning silence","A heavy burden","A sudden drowsiness"], a:0, why:"If it is right, the Lord causes the bosom to burn within you, so you feel that it is right." }
    ] },
  { n:10, summary:"After wicked men obtained and altered the translated manuscript that Joseph Smith had given to Martin Harris, the Lord explained Satan's cunning plan: if Joseph translated the same words again, his enemies would claim he had lied and contradicted himself, thereby destroying his testimony and the work. To defeat this design, the Lord commanded Joseph not to retranslate those lost pages but to translate the plates of Nephi, a more particular account containing the same record, which would confound those who had altered His words. The Lord declared that His wisdom is greater than the cunning of the devil and that Satan flatters men that it is no sin to lie in order to catch another. He also taught that He would bring forth the gospel the ancient prophets prayed for, that His church would be established, and that whoever repents and comes unto Him is His church.",
    context:"Given through Joseph Smith between summer 1828 and May 1829, addressing the loss of the manuscript pages to Martin Harris.",
    keyVerses:[
      { ref:"D&C 10:43", text:"I will not suffer that they shall destroy my work; yea, I will show unto them that my wisdom is greater than the cunning of the devil." },
      { ref:"D&C 10:67", text:"Behold, this is my doctrine—whosoever repenteth and cometh unto me, the same is my church." },
      { ref:"D&C 10:5", text:"Pray always, that you may come off conqueror; yea, that you may conquer Satan, and that you may escape the hands of the servants of Satan that do uphold his work." }
    ],
    takeaway:"God's wisdom outmatches every scheme against His work; pray always and build on Christ's doctrine of repentance.",
    quiz:[
      { q:"What had Satan put into the hearts of wicked men to do with the lost manuscript words?", choices:["Alter the words that had been translated","Publish them immediately to the world","Return them to Joseph unchanged","Translate them into other languages"], a:0, why:"The Lord said Satan put it into their hearts to alter the words which had been written, planning to accuse Joseph of contradiction." },
      { q:"What solution did the Lord give to confound those who altered the words?", choices:["Translate the lost pages again from memory","Translate the engravings on the plates of Nephi instead","Wait until the enemies confessed","Ask Martin Harris to testify"], a:1, why:"Joseph was told to translate the more particular plates of Nephi and publish it as the record of Nephi, confounding those who altered the words." },
      { q:"What does the Lord identify as His doctrine regarding His church?", choices:["Whosoever attends meetings regularly is His church","Whosoever pays tithing is His church","Whosoever keeps every tradition is His church","Whosoever repenteth and cometh unto Him, the same is His church"], a:3, why:"The Lord declared that whoever repents and comes unto Him is His church, and enduring to the end establishes them on His rock." }
    ] },
  { n:11, summary:"When Hyrum Smith desired to assist in the coming forth of the great and marvelous work, the Lord answered with counsel echoing earlier revelations: the field was white already to harvest, and whoever desired to reap was called of God. Hyrum was told to seek to establish the cause of Zion, to seek not riches but wisdom, and to say nothing but repentance unto this generation. The Lord acknowledged Hyrum's desire to preach but instructed him not to suppose he was called to preach until he was called; he should first seek to obtain the Lord's word, and then his tongue would be loosed with power to convince men. The Lord commanded him to study the word then coming forth, to deny not the spirit of revelation or prophecy, and to cleave unto the Lord with all his heart until he could assist in bringing the translation to light.",
    context:"Given through Joseph Smith in May 1829 at Harmony, Pennsylvania, to his older brother Hyrum Smith.",
    keyVerses:[
      { ref:"D&C 11:7", text:"Seek not for riches but for wisdom; and, behold, the mysteries of God shall be unfolded unto you, and then shall you be made rich." },
      { ref:"D&C 11:21", text:"Seek not to declare my word, but first seek to obtain my word, and then shall your tongue be loosed" },
      { ref:"D&C 11:25", text:"Deny not the spirit of revelation, nor the spirit of prophecy, for wo unto him that denieth these things" }
    ],
    takeaway:"Prepare quietly before preaching: first obtain God's word, then share it with power.",
    quiz:[
      { q:"To whom was this revelation given?", choices:["David Whitmer","Hyrum Smith","Joseph Smith Sr.","John Whitmer"], a:1, why:"The Lord addressed Hyrum directly, saying, Behold thou art Hyrum, my son; seek the kingdom of God." },
      { q:"What was Hyrum told to do before declaring the word?", choices:["Travel to Missouri","Raise funds for printing","Gather a congregation","First seek to obtain the word"], a:3, why:"Hyrum was told not to seek to declare the word until he first obtained it, after which his tongue would be loosed with God's power." },
      { q:"What warning accompanied the command to treasure up truth until the time to go forth?", choices:["Never write anything down","Avoid all contact with unbelievers","Deny not the spirit of revelation or prophecy","Speak only in private homes"], a:2, why:"Hyrum was warned to deny not the spirit of revelation nor the spirit of prophecy, for wo comes to those who deny them." }
    ] },
  { n:12, summary:"This short revelation repeated the announcement that a great and marvelous work was about to come forth, that the word of God is quick and powerful, sharper than a two-edged sword, and that the field is white already to harvest. Whoever desired to reap was invited to thrust in the sickle with his might and treasure up everlasting salvation, for whoever would thrust in the sickle and reap was called of God. The person addressed was urged to keep the commandments and seek to bring forth and establish the cause of Zion. The Lord added a defining qualification: no one can assist in this work except he shall be humble and full of love, having faith, hope, and charity, being temperate in all things whatsoever is entrusted to his care. Speaking as the light and life of the world, the Lord declared that heeding with might made one called.",
    context:"Given through Joseph Smith in May 1829 at Harmony, Pennsylvania, to Joseph Knight Sr., who supplied provisions during the translation.",
    keyVerses:[
      { ref:"D&C 12:8", text:"And no one can assist in this work except he shall be humble and full of love, having faith, hope, and charity, being temperate in all things, whatsoever shall be entrusted to his care." },
      { ref:"D&C 12:3", text:"Behold, the field is white already to harvest; therefore, whoso desireth to reap let him thrust in his sickle with his might" }
    ],
    takeaway:"Humility, love, faith, hope, charity, and temperance qualify us to help the Lord's work.",
    quiz:[
      { q:"According to section 12, what qualities must a person have to assist in the work?", choices:["Boldness, wealth, and influence","Silence, solitude, and fasting","Humility, love, faith, hope, charity, and temperance","Knowledge of languages and history"], a:2, why:"The Lord said no one can assist except he be humble and full of love, having faith, hope, and charity, being temperate in all things." },
      { q:"How is one called to labor in this section's harvest field?", choices:["Whoever desireth to reap may thrust in the sickle","Only elders may reap","Reapers must first see an angel","Reaping waits until harvest season ends"], a:0, why:"The revelation states that whosoever will thrust in his sickle and reap, the same is called of God." },
      { q:"What cause was the hearer commanded to bring forth and establish?", choices:["A school of the prophets","A printing press","A city of refuge","The cause of Zion"], a:3, why:"The revelation twice instructed the hearer to keep the commandments and seek to bring forth and establish the cause of Zion." }
    ] },
  { n:13, summary:"Along the Susquehanna River in May 1829, John the Baptist appeared as a resurrected being to Joseph Smith and Oliver Cowdery, laid his hands upon their heads, and ordained them to the Aaronic Priesthood. Speaking in the name of Messiah, he conferred the Priesthood of Aaron, which holds the keys of the ministering of angels, of the gospel of repentance, and of baptism by immersion for the remission of sins. He declared that this priesthood would never again be taken from the earth until the sons of Levi offered an offering to the Lord in righteousness. The ordinance fulfilled the promise made about baptism and opened the way for Joseph and Oliver to baptize each other for the remission of sins.",
    context:"Conferred by the resurrected John the Baptist on Joseph Smith and Oliver Cowdery on May 15, 1829, near Harmony, Pennsylvania.",
    keyVerses:[
      { ref:"D&C 13:1", text:"Upon you my fellow servants, in the name of Messiah I confer the Priesthood of Aaron, which holds the keys of the ministering of angels, and of the gospel of repentance, and of baptism by immersion for the remission of sins" }
    ],
    takeaway:"Angelic authority restores access to repentance, baptism, and ministering angels for everyone.",
    quiz:[
      { q:"Who conferred the Priesthood of Aaron on Joseph Smith and Oliver Cowdery?", choices:["Peter, James, and John","Elijah the prophet","Moroni","John the Baptist"], a:3, why:"John the Baptist, as a resurrected messenger, ordained them saying he conferred the Priesthood of Aaron in the name of Messiah." },
      { q:"What three keys or functions does the Aaronic Priesthood hold?", choices:["Sealing, healing, and prophecy","Ministering of angels, the gospel of repentance, and baptism by immersion for the remission of sins","Translation, revelation, and vision","Consecration, gathering, and temple work"], a:1, why:"The messenger said this priesthood holds keys of the ministering of angels, the gospel of repentance, and baptism by immersion for the remission of sins." },
      { q:"How long did John say the Aaronic Priesthood would remain on the earth?", choices:["It shall never be taken again until the sons of Levi offer an offering in righteousness","Only until the church was organized","Until the Melchizedek Priesthood was restored","Only during Joseph Smith's lifetime"], a:0, why:"John declared the priesthood would never be taken again until the sons of Levi do offer again an offering unto the Lord in righteousness." }
    ] },
  { n:14, summary:"Using the familiar opening about a great and marvelous work coming forth and a field white already to harvest, the Lord answered David Whitmer's desire to help. He was told to seek to bring forth and establish the Lord's Zion, keep the commandments in all things, and endure to the end, with the promise that endurance brings eternal life, the greatest of all the gifts of God. The Lord promised that if David asked the Father in faith, he would receive the Holy Ghost, which giveth utterance, enabling him to stand as a witness of what he heard and saw and to declare repentance to this generation. Identifying Himself as Jesus Christ, the Son of the living God, who created the heavens and the earth, the Lord said He must bring forth the fulness of His gospel from the Gentiles to the house of Israel, and that David was called to assist.",
    context:"Given through Joseph Smith in June 1829 at Fayette, New York, for David Whitmer, who desired to assist in the work.",
    keyVerses:[
      { ref:"D&C 14:7", text:"And, if you keep my commandments and endure to the end you shall have eternal life, which gift is the greatest of all the gifts of God." },
      { ref:"D&C 14:8", text:"And it shall come to pass, that if you shall ask the Father in my name, in faith believing, you shall receive the Holy Ghost, which giveth utterance" }
    ],
    takeaway:"Endure to the end in obedience and the greatest gift, eternal life, awaits.",
    quiz:[
      { q:"Who was named in this revelation as called to assist in the work?", choices:["David","Peter","John","James"], a:0, why:"The Lord said, thou art David, and thou art called to assist; if faithful, he would be blessed spiritually and temporally." },
      { q:"What did the Lord promise David if he asked the Father in faith?", choices:["Wealth and land","Immediate ordination as an apostle","The Holy Ghost, which giveth utterance","A written copy of the plates"], a:2, why:"The Lord promised that asking the Father in faith believing would bring the Holy Ghost, which giveth utterance, so David could stand as a witness." },
      { q:"What is identified as the greatest of all the gifts of God?", choices:["The ministering of angels","Eternal life","The power to translate","The spirit of prophecy"], a:1, why:"The Lord taught that keeping His commandments and enduring to the end brings eternal life, which gift is the greatest of all the gifts of God." }
    ] },
  { n:15, summary:"John Whitmer had many times desired to know what would be of the most worth to him, and this revelation answered. The Lord, speaking with sharpness and power because His arm is over all the earth, blessed John for desiring to know and for speaking the words given him by commandment. The answer declared that the thing of most worth would be to declare repentance unto this people, so that John might bring souls to Christ and rest with them in the kingdom of the Father. The revelation thus crowned the work of saving souls as the highest pursuit a person can undertake.",
    context:"Given through Joseph Smith in June 1829 at Fayette, New York, in answer to John Whitmer's question about worth.",
    keyVerses:[
      { ref:"D&C 15:4", text:"For many times you have desired of me to know that which would be of the most worth unto you." },
      { ref:"D&C 15:6", text:"And now, behold, I say unto you, that the thing which will be of the most worth unto you will be to declare repentance unto this people, that you may bring souls unto me" }
    ],
    takeaway:"Bringing souls to Christ through declaring repentance is the work of greatest worth.",
    quiz:[
      { q:"What question had John repeatedly desired to ask the Lord?", choices:["Where should he live?","What would be of the most worth unto him?","When would the church be organized?","How should the records be translated?"], a:1, why:"The Lord acknowledged that many times John had desired to know that which would be of the most worth unto him." },
      { q:"What did the Lord name as the thing of most worth?", choices:["Acquiring property in the new gathering","Mastering the scriptures quickly","Declaring repentance to bring souls unto Christ","Recording the history of the translation"], a:2, why:"The thing of most worth was to declare repentance, bringing souls to Christ to rest with them in the kingdom of the Father." },
      { q:"Why did the Lord say He spoke with sharpness and power?", choices:["Because mine arm is over all the earth","Because John had sinned","Because the church was in rebellion","Because angels demanded it"], a:0, why:"The Lord stated He spoke with sharpness and power because His arm is over all the earth." }
    ] },
  { n:16, summary:"Peter Whitmer Jr., like his brother John, had many times desired to know what would be of the most worth to him, and the Lord answered him directly. Speaking with sharpness and power because His arm is over all the earth, the Lord blessed Peter for the desire and for speaking the words given him by commandment. The answer declared that the thing of most worth would be to declare repentance unto this people, so that Peter might bring souls to Christ and rest with them in the kingdom of the Father. Given at nearly the same moment as John's answer, the revelation showed that the Lord deals personally with each servant, giving the same saving commission to every willing heart.",
    context:"Given through Joseph Smith in June 1829 at Fayette, New York, in answer to Peter Whitmer Jr.'s question.",
    keyVerses:[
      { ref:"D&C 16:3", text:"And I will tell you that which no man knoweth save me and thee alone" },
      { ref:"D&C 16:6", text:"And now, behold, I say unto you, that the thing which will be of the most worth unto you will be to declare repentance unto this people, that you may bring souls unto me" }
    ],
    takeaway:"The Lord knows each servant by name and gives the same commission: bring souls to Him.",
    quiz:[
      { q:"Who is the servant addressed in section 16?", choices:["John Whitmer","David Whitmer","Peter Whitmer Jr.","Oliver Cowdery"], a:2, why:"The revelation opens, Hearken, my servant Peter, and listen to the words of Jesus Christ, your Lord and your Redeemer." },
      { q:"What did the Lord say would be of most worth to Peter?", choices:["Staying safely at home","Gaining scholarly learning","Leading large crowds","Declaring repentance and bringing souls unto Christ"], a:3, why:"The Lord told Peter that declaring repentance to bring souls to Him, so they could rest together in the Father's kingdom, was of most worth." },
      { q:"What does this revelation reveal about how the Lord gives personal guidance?", choices:["He answers only prophets as a group","He tells individuals that which no man knoweth save Him and them alone","He repeats identical words without regard to the person","He waits for committees to ask"], a:1, why:"The Lord promised Peter, I will tell you that which no man knoweth save me and thee alone." }
    ] },
  { n:17, summary:"This revelation told Oliver Cowdery, David Whitmer, and Martin Harris that by relying on the word of the Lord with full purpose of heart, they would receive a view of the plates, the breastplate, the sword of Laban, the Urim and Thummim given to the brother of Jared, and the miraculous directors given to Lehi in the wilderness. Obtained by faith like that of the prophets of old, the view would come after they had obtained faith, and then they would testify of what they saw by the power of God. The purpose was twofold: that Joseph Smith might not be destroyed, and that the Lord's righteous purposes might come to pass. The three were promised the same power, faith, and gift as Joseph, who had translated the book by that same power, and were assured that the gates of hell would not prevail against the obedient.",
    context:"Given through Joseph Smith in June 1829 at Fayette, New York, for the three men who would become the Three Witnesses.",
    keyVerses:[
      { ref:"D&C 17:1", text:"Behold, I say unto you, that you must rely upon my word, which if you do with full purpose of heart, you shall have a view of the plates" },
      { ref:"D&C 17:2", text:"And it is by your faith that you shall obtain a view of them, even by that faith which was had by the prophets of old." }
    ],
    takeaway:"Faith in God's word opens heaven's evidence; witnessing of it protects the work.",
    quiz:[
      { q:"Which ancient objects did the Lord promise the witnesses would see besides the plates?", choices:["The ark of the covenant","The brass serpent of Moses","The liahona only","The breastplate, the sword of Laban, the Urim and Thummim, and the directors"], a:3, why:"The Lord listed the breastplate, sword of Laban, Urim and Thummim given to the brother of Jared, and the miraculous directors given to Lehi." },
      { q:"By what means were the witnesses told they would obtain a view of these sacred objects?", choices:["By faith like that of the prophets of old","By legal testimony from neighbors","By studying Egyptian characters","By wearing the breastplate"], a:0, why:"The revelation states it is by your faith that you shall obtain a view of them, even the faith had by the prophets of old." },
      { q:"Why did the Lord say the testimony of these witnesses was needed?", choices:["To sell copies of the book","To satisfy Martin Harris's curiosity","That Joseph Smith might not be destroyed","To choose the first elders"], a:2, why:"The Lord explained the witnesses would testify so that His servant Joseph Smith might not be destroyed and His righteous purposes could be accomplished." }
    ] },
  { n:18, summary:"Answering Oliver Cowdery's desire to know, the Lord confirmed that what had been written was true, manifested by His Spirit in many instances, and commanded Oliver to rely on the scriptures being brought forth, for they contain all things concerning the foundation of the church, the gospel, and the rock. The world was ripening in iniquity and needed to be stirred to repentance. The Lord spoke to Oliver and David Whitmer with the same calling as the Apostle Paul, teaching that the worth of souls is great because the Redeemer suffered the pain of all men that all might repent. Laboring all one's days to bring even one soul to Christ would bring great joy, and bringing many would bring greater. The section also revealed that twelve disciples would be called to preach and baptize, and commissioned Oliver and David to search out the Twelve by their desires and their works.",
    context:"Given through Joseph Smith in June 1829 at Fayette, New York, to Oliver Cowdery and David Whitmer about calling the Twelve.",
    keyVerses:[
      { ref:"D&C 18:10", text:"Remember the worth of souls is great in the sight of God" },
      { ref:"D&C 18:15", text:"And if it so be that you should labor all your days in crying repentance unto this people, and bring, save it be one soul unto me, how great shall be your joy with him in the kingdom of my Father!" },
      { ref:"D&C 18:19", text:"And if you have not faith, hope, and charity, you can do nothing." }
    ],
    takeaway:"Souls are precious to God; labor to bring even one to Christ and your joy will be great.",
    quiz:[
      { q:"Who was commanded with Oliver to search out the Twelve?", choices:["David Whitmer","Martin Harris","Hyrum Smith","Joseph Smith Sr."], a:0, why:"The Lord said He gave unto Oliver Cowdery and also unto David Whitmer the commission to search out the Twelve." },
      { q:"Why is the worth of souls so great, according to this section?", choices:["Because souls outnumber the stars","Because every soul holds property","Because souls can translate records","Because the Redeemer suffered the pain of all men that all might repent"], a:3, why:"The Lord explained that He suffered death in the flesh and the pain of all men so all might repent and come unto Him." },
      { q:"How would Oliver and David know those chosen for the Twelve?", choices:["By the height of their faith as measured by Joseph","By their desires and their works","By a drawing of lots","By a vote of the crowds"], a:1, why:"The Lord said that by their desires and their works you shall know them, matching the desires He described for disciples." }
    ] },
  { n:19, summary:"Speaking as Alpha and Omega, the Redeemer of the world, the Lord revealed deep doctrine about His suffering and judgment. Every person must repent or suffer, for the Lord explained that endless and eternal punishment is God's punishment, named for Endless, His name, rather than describing unending duration for every case. He then described His own atoning suffering: He suffered for all so they would not need to suffer if they repented, a suffering that made even God, the greatest of all, tremble because of pain and bleed at every pore. Commanding Martin Harris to repent, preach naught but repentance, and keep the commandments received through Joseph Smith, the Lord also instructed him not to covet his neighbor's wife or life, to impart his property to print the Book of Mormon, to pay the debt owed the printer, and to pray vocally and in secret.",
    context:"Given through Joseph Smith around the summer of 1829 at Manchester, New York, chiefly to Martin Harris.",
    keyVerses:[
      { ref:"D&C 19:10", text:"For, behold, the mystery of godliness, how great is it! For, behold, I am endless, and the punishment which is given from my hand is endless punishment, for Endless is my name." },
      { ref:"D&C 19:16", text:"For behold, I, God, have suffered these things for all, that they might not suffer if they would repent" },
      { ref:"D&C 19:23", text:"Learn of me, and listen to my words; walk in the meekness of my Spirit, and you shall have peace in me." }
    ],
    takeaway:"Christ suffered so repentance can spare us; learn of Him and walk in meekness for peace.",
    quiz:[
      { q:"What did the Lord reveal about the meaning of endless punishment?", choices:["It always lasts forever for everyone","Endless is God's name, so endless punishment is God's punishment","It ends after a thousand years","It applies only to apostles"], a:1, why:"The Lord explained that Endless is my name, so eternal and endless punishment mean God's punishment rather than an unending duration in every case." },
      { q:"How did the Lord describe His own suffering in this section?", choices:["It caused Him to tremble because of pain and bleed at every pore","It was brief and light","He did not suffer at all","He suffered only physically, not spiritually"], a:0, why:"The Lord said the suffering caused Him, even God, the greatest of all, to tremble because of pain and to bleed at every pore." },
      { q:"What financial obligations did the Lord place on Martin Harris?", choices:["Buy land for the temple","Pay tithing of one tenth","Impart property to print the Book of Mormon and pay the debt owed the printer","Donate all money to the government"], a:2, why:"Martin was commanded to impart part of his property and lands to printing, and to pay the debt he had contracted with the printer." }
    ] },
  { n:20, summary:"This charter records that the Church of Christ was organized on April 6, 1830, with Joseph Smith as first elder and Oliver Cowdery as second elder. It recounts how the first elder, after receiving a remission of sins and again humbling himself, was ministered to by a holy angel and given power to translate the Book of Mormon, which proves the holy scriptures true and shows that God inspires men and calls them to His work in every age. The section then sets forth core doctrines: God created man male and female in His image; man fell; the Only Begotten Son suffered temptations, was crucified, died, rose again, and ascended to the Father's right hand; the Father, Son, and Holy Ghost are one God; and all must repent, be baptized, and endure to the end, since justification and sanctification come through grace. The remainder prescribes duties of elders, priests, teachers, and deacons, the manner of baptism, blessing children, and administering bread and wine in remembrance of Christ.",
    context:"Given through Joseph Smith at the organization of the Church on April 6, 1830, in Fayette, New York.",
    keyVerses:[
      { ref:"D&C 20:17", text:"By these things we know that there is a God in heaven, who is infinite and eternal, from everlasting to everlasting the same unchangeable God, the framer of heaven and earth, and all things which are in them" },
      { ref:"D&C 20:28", text:"Which Father, Son, and Holy Ghost are one God, infinite and eternal, without end. Amen." },
      { ref:"D&C 20:37", text:"And again, by way of commandment to the church concerning the manner of baptism—All those who humble themselves before God, and desire to be baptized, and come forth with broken hearts and contrite spirits" }
    ],
    takeaway:"The risen Christ organizes His church so repentance, baptism, and sacrament can lead us home.",
    quiz:[
      { q:"When and where was the Church of Christ organized according to this section?", choices:["April 6, 1829, at Harmony, Pennsylvania","June 15, 1829, at Fayette, New York","April 6, 1830, according to the laws of the country","January 1, 1831, at Kirtland, Ohio"], a:2, why:"The opening verses state the church was organized on the sixth day of April 1830, agreeable to the laws of the country." },
      { q:"What power did the holy angel give Joseph Smith, according to this account?", choices:["Authority to ordain kings","Power from on high to translate the Book of Mormon","The keys to seal families","The gift of healing"], a:1, why:"The revelation says God gave him power from on high, by prepared means, to translate the Book of Mormon." },
      { q:"What doctrine does section 20 teach about the Father, Son, and Holy Ghost?", choices:["They are three separate gods without unity","They are titles for one person","Only the Father is eternal","They are one God, infinite and eternal, without end"], a:3, why:"The doctrinal declaration states that the Father, Son, and Holy Ghost are one God, infinite and eternal, without end." }
    ] }
);
